    18	    private static Map<String, Object> immutableMap(Map<?, ?> source) {
    19	        Map<String, Object> copy = new LinkedHashMap<>();
    20	        source.forEach((key, value) -> {
    21	            if (!(key instanceof String stringKey) || stringKey.isBlank()) {
    22	                throw new IllegalArgumentException("Fact keys must be nonblank strings");
    23	            }
